**Location:** src/lib/stores/appStore.ts:69-76

**Problem:** The `updateFilteredNotes` function has an incomplete implementation with a TODO-like comment. When a search query is provided, it just returns all notes instead of filtering:

```typescript
export function updateFilteredNotes(allNotes: DecryptedNote[], query: string) {
  if (!query.trim()) {
    filteredNotes.set(allNotes);
  } else {
    // Will use searchService in App.svelte
    filteredNotes.set(allNotes);  // BUG: Returns all notes, ignores query!
  }
}
```

**Impact:** This function appears unused (App.svelte handles search directly), but if called, it would fail to filter notes.

**Remediation:**
Either:
1. Remove this function if it's dead code
2. Or implement it properly by calling searchService:

```typescript
import { searchService } from '../services/searchService';

export async function updateFilteredNotes(
  allNotes: DecryptedNote[], 
  query: string,
  sortOrder: SortOrder = 'recent',
  archiveMode: boolean = false
) {
  if (!query.trim()) {
    filteredNotes.set(allNotes);
  } else {
    const results = await searchService.searchNotes(query, allNotes, sortOrder, archiveMode);
    filteredNotes.set(results);
  }
}
```

